<details data-bee-question class="bee-question" @if(!is_int($index))open @endif><summary><strong>{{ $kind==='regular' ? 'Question' : 'Tie-breaker' }} <span data-bee-question-number>{{ is_int($index) ? $index+1 : '' }}</span></strong> · {{ mb_strimwidth($question['prompt'] ?? '',0,80,'…') ?: 'New question' }}</summary><div class="bee-form"><label>Question<input name="questions[{{ $level }}][{{ $kind }}][{{ $index }}][prompt]" value="{{ $question['prompt'] ?? '' }}" required maxlength="1000"></label><div class="bee-field-grid">@for($choice=0;$choice<4;$choice++)<label>Choice {{ $choice+1 }}<input name="questions[{{ $level }}][{{ $kind }}][{{ $index }}][options][{{ $choice }}]" value="{{ $question['options'][$choice] ?? '' }}" required maxlength="500"></label>@endfor</div><label>Correct answer<select name="questions[{{ $level }}][{{ $kind }}][{{ $index }}][correct]" required>@for($choice=0;$choice<4;$choice++)<option value="{{ $choice }}" @selected((int)($question['correct'] ?? 0)===$choice)>Choice {{ $choice+1 }}</option>@endfor</select></label><label>Explanation shown after the question closes<textarea name="questions[{{ $level }}][{{ $kind }}][{{ $index }}][why]" rows="2" maxlength="1000">{{ $question['why'] ?? '' }}</textarea></label>@if($kind==='regular')<button type="button" class="bee-button" data-bee-remove-question>Remove regular question</button>@endif</div></details>
